    22→// StatusCollector gathers live status from Docker, config, and state files.
    23→type StatusCollector struct {
    24→	Config  *config.Config
    25→	DataDir string
    26→	Logger  *slog.Logger
    27→	Caddy   *caddy.CaddyManager
    28→	Preview *preview.PreviewManager
    29→}
