    31→// ServerStatus holds a complete snapshot of the server's runtime state.
    32→type ServerStatus struct {
    33→	ServerName      string          `json:"server_name"`
    34→	Caddy           CaddyStatus     `json:"caddy"`
    35→	Apps            []AppStatus     `json:"apps,omitempty"`
    36→	Stacks          []StackStatus   `json:"stacks,omitempty"`
    37→	Previews        []PreviewStatus `json:"previews,omitempty"`
    38→	Webhooks        []WebhookStatus `json:"webhooks,omitempty"`
    39→	WebhookSyncedAt time.Time       `json:"webhook_synced_at,omitzero"`
    40→}
