    42→// CaddyStatus describes the current state of the Caddy reverse proxy.
    43→type CaddyStatus struct {
    44→	Running     bool   `json:"running"`
    45→	Uptime      string `json:"uptime,omitzero"`
    46→	Email       string `json:"email,omitzero"`
    47→	DomainCount int    `json:"domain_count,omitzero"`
    48→}
    49→
    50→// AppStatus describes the runtime state of a configured app.
    51→type AppStatus struct {
    52→	Name            string `json:"name"`
    53→	Domain          string `json:"domain"`
    54→	Branch          string `json:"branch"`
    55→	State           string `json:"state"` // "running", "degraded", "stopped", "not deployed", "error"
    56→	ContainersUp    int    `json:"containers_up,omitzero"`
    57→	ContainersTotal int    `json:"containers_total,omitzero"`
    58→	LastCommit      string `json:"last_commit,omitzero"`
    59→}
    60→
    61→// StackStatus describes the runtime state of a configured stack.
    62→type StackStatus struct {
    63→	Name            string `json:"name"`
    64→	Domain          string `json:"domain"`
