   100→// WebhookStatePath returns the path to webhooks.json.
   101→func WebhookStatePath(dataDir string) string {
   102→	return filepath.Join(dataDir, "webhooks.json")
   103→}
   104→
   105→// SaveWebhookState writes the webhook state to disk atomically.
   106→func SaveWebhookState(path string, state *WebhookState) error {
   107→	data, err := json.MarshalIndent(state, "", "  ")
   108→	if err != nil {
   109→		return fmt.Errorf("marshaling webhook state: %w", err)
   110→	}
   111→	tmp := path + ".tmp"
   112→	if err := os.WriteFile(tmp, data, 0644); err != nil {
   113→		return fmt.Errorf("writing webhook state: %w", err)
   114→	}
   115→	if err := os.Rename(tmp, path); err != nil {
   116→		os.Remove(tmp) //nolint:errcheck
   117→		return fmt.Errorf("renaming webhook state: %w", err)
   118→	}
   119→	return nil
   120→}
