   122→// Collect gathers live status from all sources concurrently.
   123→// It completes within 10 seconds even with many services.
   124→func (c *StatusCollector) Collect(ctx context.Context) (*ServerStatus, error) {
   125→	s := &ServerStatus{
   126→		ServerName: c.Config.Server.Name,
   127→	}
   128→
   129→	// Caddy status.
   130→	if c.Caddy != nil {
   131→		cs, err := c.Caddy.Status(ctx)
   132→		if err != nil {
   133→			c.Logger.Warn("could not get caddy status", "error", err)
   134→		} else {
   135→			s.Caddy = CaddyStatus{
   136→				Running:     cs.Running,
   137→				Uptime:      cs.Uptime,
   138→				Email:       cs.Email,
   139→				DomainCount: len(cs.Domains),
   140→			}
   141→		}
   142→	}
   143→
   144→	// App statuses (concurrent).
   145→	appNames := slices.Sorted(maps.Keys(c.Config.Apps))
   146→	appStatuses := make([]AppStatus, len(appNames))
   147→	var wg sync.WaitGroup
   148→	for i, name := range appNames {
   149→		wg.Go(func() {
   150→			appStatuses[i] = c.collectAppStatus(ctx, name, c.Config.Apps[name])
   151→		})
   152→	}
   153→	wg.Wait()
   154→	s.Apps = appStatuses
   155→
   156→	// Stack statuses (concurrent).
   157→	stackNames := slices.Sorted(maps.Keys(c.Config.Stacks))
   158→	stackStatuses := make([]StackStatus, len(stackNames))
   159→	for i, name := range stackNames {
   160→		wg.Go(func() {
   161→			stackStatuses[i] = c.collectStackStatus(ctx, name, c.Config.Stacks[name])
   162→		})
   163→	}
   164→	wg.Wait()
   165→	s.Stacks = stackStatuses
   166→
   167→	// Preview statuses.
   168→	if c.Preview != nil {
   169→		previews, err := c.Preview.List()
   170→		if err != nil {
   171→			c.Logger.Warn("could not list previews", "error", err)
   172→		} else {
   173→			ps := make([]PreviewStatus, len(previews))
   174→			for i, p := range previews {
   175→				ps[i] = PreviewStatus{
   176→					AppName:   p.AppName,
   177→					Domain:    p.Domain,
   178→					Branch:    p.Branch,
   179→					Age:       formatAge(time.Since(p.CreatedAt)),
   180→					Commit:    p.Commit,
   181→					CreatedAt: p.CreatedAt,
   182→				}
   183→			}
   184→			s.Previews = ps
   185→		}
   186→	}
   187→
   188→	// Webhook statuses.
   189→	s.Webhooks, s.WebhookSyncedAt = c.collectWebhookStatuses()
   190→
   191→	return s, nil
   192→}
