   194→func (c *StatusCollector) collectAppStatus(ctx context.Context, name string, app config.App) AppStatus {
   195→	s := AppStatus{
   196→		Name:   name,
   197→		Domain: app.Domain,
   198→		Branch: app.Branch,
   199→	}
   200→
   201→	appDir := filepath.Join(c.Config.Server.StacksDir, "apps", name)
   202→	if _, err := os.Stat(appDir); os.IsNotExist(err) {
   203→		s.State = "not deployed"
   204→		return s
   205→	}
   206→
   207→	repoDir := filepath.Join(appDir, "repo")
   208→	if commit, err := readGitHead(ctx, repoDir); err == nil {
   209→		s.LastCommit = commit
   210→	}
   211→
   212→	up, total, state, err := queryDockerCompose(ctx, "herald-"+name)
   213→	if err != nil {
   214→		c.Logger.Warn("docker compose ps failed", "app", name, "error", err)
   215→		s.State = "error"
   216→		return s
   217→	}
   218→	s.ContainersUp = up
   219→	s.ContainersTotal = total
   220→	s.State = state
   221→	return s
   222→}
   223→
   224→func (c *StatusCollector) collectStackStatus(ctx context.Context, name string, stack config.Stack) StackStatus {
   225→	s := StackStatus{
   226→		Name:   name,
   227→		Domain: stack.Domain,
   228→	}
   229→
   230→	up, total, state, err := queryDockerCompose(ctx, "herald-stack-"+name)
   231→	if err != nil {
   232→		c.Logger.Warn("docker compose ps failed", "stack", name, "error", err)
   233→		s.State = "error"
   234→		return s
   235→	}
   236→	s.ContainersUp = up
   237→	s.ContainersTotal = total
   238→	s.State = state
   239→	return s
   240→}
