   242→func (c *StatusCollector) collectWebhookStatuses() ([]WebhookStatus, time.Time) {
   243→	repos := uniqueRepos(c.Config)
   244→	wsPath := WebhookStatePath(c.DataDir)
   245→
   246→	data, err := os.ReadFile(wsPath)
   247→	if err != nil {
   248→		// File not found — show "unknown" for all repos.
   249→		statuses := make([]WebhookStatus, len(repos))
   250→		for i, repo := range repos {
   251→			statuses[i] = WebhookStatus{Repo: repo, Unknown: true}
   252→		}
   253→		return statuses, time.Time{}
   254→	}
   255→
   256→	var state WebhookState
   257→	if err := json.Unmarshal(data, &state); err != nil {
   258→		c.Logger.Warn("could not parse webhooks.json", "error", err)
   259→		statuses := make([]WebhookStatus, len(repos))
   260→		for i, repo := range repos {
   261→			statuses[i] = WebhookStatus{Repo: repo, Unknown: true}
   262→		}
   263→		return statuses, time.Time{}
   264→	}
   265→
   266→	statuses := make([]WebhookStatus, len(repos))
   267→	for i, repo := range repos {
   268→		entry, ok := state.Repos[repo]
   269→		statuses[i] = WebhookStatus{
   270→			Repo:       repo,
   271→			Registered: ok && entry.Registered,
   272→			ID:         entry.ID,
   273→		}
   274→	}
   275→	return statuses, state.SyncedAt
   276→}
