   278→// containerPS holds the container state fields from `docker compose ps --format json`.
   279→type containerPS struct {
   280→	State string `json:"State"`
   281→}
   282→
   283→// queryDockerCompose runs `docker compose -p <project> ps --format json` and
   284→// returns (running_count, total_count, state_string, error).
   285→// On Docker error or missing project, returns (0, 0, "stopped", nil).
   286→func queryDockerCompose(ctx context.Context, project string) (up, total int, state string, err error) {
   287→	cmd := exec.CommandContext(ctx, "docker", "compose", "-p", project, "ps", "--format", "json")
   288→	out, runErr := cmd.Output()
   289→	if runErr != nil {
   290→		// Docker not accessible or project not found → treat as stopped.
   291→		return 0, 0, "stopped", nil
   292→	}
   293→
   294→	containers, parseErr := parseComposePSOutput(out)
   295→	if parseErr != nil {
   296→		return 0, 0, "error", parseErr
   297→	}
   298→
   299→	up, total, state = computeState(containers)
   300→	return up, total, state, nil
   301→}
   302→
   303→// parseComposePSOutput parses `docker compose ps --format json` output.
   304→// Docker Compose v2 outputs NDJSON (one object per line), but older versions
   305→// may output a JSON array.
   306→func parseComposePSOutput(out []byte) ([]containerPS, error) {
   307→	output := strings.TrimSpace(string(out))
   308→	if output == "" || output == "[]" || output == "null" {
   309→		return nil, nil
   310→	}
   311→
   312→	// Try JSON array first.
   313→	if strings.HasPrefix(output, "[") {
   314→		var containers []containerPS
   315→		if err := json.Unmarshal([]byte(output), &containers); err != nil {
   316→			return nil, fmt.Errorf("parsing docker compose ps output: %w", err)
   317→		}
   318→		return containers, nil
   319→	}
   320→
   321→	// NDJSON: one JSON object per line.
   322→	var containers []containerPS
   323→	for _, line := range strings.Split(output, "\n") {
   324→		line = strings.TrimSpace(line)
   325→		if line == "" {
   326→			continue
   327→		}
   328→		var c containerPS
   329→		if err := json.Unmarshal([]byte(line), &c); err != nil {
   330→			continue // skip unparseable lines
   331→		}
   332→		containers = append(containers, c)
   333→	}
   334→	return containers, nil
   335→}
   336→
   337→// computeState derives the state string from a list of containers.
   338→func computeState(containers []containerPS) (up, total int, state string) {
   339→	total = len(containers)
   340→	for _, c := range containers {
   341→		if strings.EqualFold(c.State, "running") {
   342→			up++
   343→		}
   344→	}
   345→	switch {
   346→	case total == 0:
   347→		state = "stopped"
   348→	case up == total:
   349→		state = "running"
   350→	case up == 0:
   351→		state = "stopped"
   352→	default:
   353→		state = "degraded"
   354→	}
   355→	return up, total, state
   356→}
   357→
   358→// readGitHead reads the short commit hash from a git repository.
   359→func readGitHead(ctx context.Context, repoDir string) (string, error) {
   360→	if _, err := os.Stat(repoDir); err != nil {
   361→		return "", err
   362→	}
   363→	out, err := exec.CommandContext(ctx, "git", "-C", repoDir, "rev-parse", "--short", "HEAD").Output()
   364→	if err != nil {
   365→		return "", err
   366→	}
   367→	return strings.TrimSpace(string(out)), nil
   368→}
   369→
   370→// uniqueRepos returns sorted, deduplicated repos from config.Apps.
   371→func uniqueRepos(cfg *config.Config) []string {
   372→	seen := make(map[string]struct{})
   373→	for _, app := range cfg.Apps {
   374→		seen[app.Repo] = struct{}{}
   375→	}
   376→	return slices.Sorted(maps.Keys(seen))
   377→}
   378→
   379→// formatAge formats a duration as a short human-readable age string.
   380→func formatAge(d time.Duration) string {
   381→	switch {
   382→	case d >= 24*time.Hour:
   383→		days := int(d.Hours() / 24)
   384→		if days == 1 {
   385→			return "1d"
   386→		}
   387→		return fmt.Sprintf("%dd", days)
   388→	case d >= time.Hour:
   389→		hours := int(d.Hours())
   390→		if hours == 1 {
   391→			return "1h"
   392→		}
   393→		return fmt.Sprintf("%dh", hours)
   394→	default:
   395→		mins := int(d.Minutes())
   396→		if mins <= 1 {
   397→			return "1m"
   398→		}
   399→		return fmt.Sprintf("%dm", mins)
   400→	}
   401→}
