    16→type Config struct {
    17→	Server Server            `yaml:"server"          json:"server"`
    18→	Apps   map[string]App    `yaml:"apps,omitempty"  json:"apps,omitempty"`
    19→	Stacks map[string]Stack  `yaml:"stacks,omitempty" json:"stacks,omitempty"`
    20→}
