    65→			IaCRepo:   getIaCRepo(dataDir),
    66→			OnIaCPush: makeIaCPushHandler(stackMgr),
    67→			OnPreviewDeploy: func(appName, branch, commit string) {
    68→				ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
    69→				defer cancel()
    70→				if err := previewMgr.Deploy(ctx, appName, branch, commit); err != nil {
