   112→		shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
   113→		defer cancel()
   114→
   115→		if err := httpSrv.Shutdown(shutdownCtx); err != nil {
   116→			return fmt.Errorf("server shutdown: %w", err)
   117→		}
   118→
   119→		d.Wait()
   120→		slog.Info("herald server stopped")
   121→		return nil
   122→	},
