   125→// getIaCRepo reads the git remote URL from the IaC repo clone and returns the
   126→// GitHub full name (e.g. "nogo/srv2"), or "" if unavailable.
   127→func getIaCRepo(dataDir string) string {
   128→	repoDir := filepath.Join(dataDir, "repo")
   129→	out, err := exec.Command("git", "-C", repoDir, "remote", "get-url", "origin").Output()
   130→	if err != nil {
   131→		return ""
   132→	}
   133→	return parseGitHubRepo(strings.TrimSpace(string(out)))
   134→}
   135→
   136→// parseGitHubRepo extracts "owner/repo" from a GitHub clone URL.
   137→func parseGitHubRepo(rawURL string) string {
   138→	rawURL = strings.TrimSuffix(rawURL, ".git")
   139→	if after, ok := strings.CutPrefix(rawURL, "https://github.com/"); ok {
   140→		return after
   141→	}
   142→	// git@github.com:owner/repo
   143→	if idx := strings.Index(rawURL, "@github.com:"); idx >= 0 {
   144→		return rawURL[idx+len("@github.com:"):]
   145→	}
   146→	return ""
   147→}
   148→
   149→// makeIaCPushHandler returns a function that triggers auto-deploy for stacks
   150→// with auto_deploy: true, and logs the rest.
   151→func makeIaCPushHandler(mgr *stacks.StackManager) func() {
   152→	return func() {
   153→		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Minute)
   154→		defer cancel()
   155→
   156→		for _, info := range mgr.List() {
   157→			if info.AutoDeploy {
   158→				slog.Info("IaC push: auto-deploying stack", "stack", info.Name)
   159→				if err := mgr.ComposeUp(ctx, info.Name); err != nil {
   160→					slog.Error("IaC push: auto-deploy failed", "stack", info.Name, "error", err)
   161→				} else {
   162→					slog.Info("IaC push: auto-deploy complete", "stack", info.Name)
   163→				}
   164→			} else {
   165→				slog.Info("IaC push: stack updated in repo (no auto-deploy)", "stack", info.Name)
   166→			}
   167→		}
   168→	}
   169→}
